components.css:
.ds-btn {
  height: 36px;
  padding: 0 14px;
  border-radius: 8px;
  border: 1px solid var(--line2);
  background: var(--s2);
  color: var(--text);
  font-weight: 500;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  white-space: nowrap;
  transition: background-color 150ms ease;
}
.ds-btn:hover:not(:disabled) {
  background: var(--s3);
}
.ds-btn.ds-pri {
  background: var(--text);
  color: var(--bg);
  border-color: var(--text);
}
.ds-btn.ds-pri:hover:not(:disabled) {
  background: #dedee3;
  border-color: #dedee3;
}
.ds-btn {font-family:var(--font-geist-sans, Geist),sans-serif;font-size:14px;line-height:1.5;}
.ds-btn:focus-visible {outline:2px solid var(--blue);outline-offset:3px;}
.ds-btn:disabled {cursor:not-allowed;color:var(--faint);background:var(--s3);border-color:var(--line);} .ds-btn {cursor:pointer;}

