.ds-btn.ds-ghost {
  background: transparent;
  border-color: transparent;
  color: var(--muted);
}
.ds-btn.ds-ghost:hover:not(:disabled) {
  background: var(--s2);
  color: var(--text);
}
.ds-btn {font-family:var(--font-geist-sans, Geist),sans-serif;font-size:14px;line-height:1.5;}
