.ds-btn:disabled {cursor:not-allowed;color:var(--faint);background:var(--s3);border-color:var(--line);} .ds-btn {cursor:pointer;}

.ds-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 18px;
}
.ds-field label,
.ds-field-label,
.ds-connection-method legend {
  font-size: 13px;
  font-weight: 500;
}
.ds-input {
  height: 38px;
  border: 1px solid var(--line2);
  background: var(--bg);
  border-radius: 8px;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 0 12px;
  color: var(--text);
  width: 100%;
  min-width: 0;
}
.ds-input:focus {
  outline: none;
  border-color: var(--blue);
  box-shadow: 0 0 0 3px var(--blue-soft);
}
.ds-field {font-family:var(--font-geist-sans, Geist),sans-serif;font-size:14px;line-height:1.5;}
.ds-field:focus-visible {outline:2px solid var(--blue);outline-offset:3px;}
.ds-input::placeholder {color:var(--faint)}

.ds-nv {
  display: flex;
  align-items: center;
  gap: 10px;
  height: 34px;
  padding: 0 10px;
  border-radius: 7px;
  color: var(--muted);
  font-weight: 500;
  position: relative;
  border: 0;
  background: transparent;
  flex-shrink: 0;
}
.ds-nv.ds-on {
  background: var(--s2);
  color: var(--text);
  box-shadow: inset 0 0 0 1px var(--line);
}
.ds-nv:hover {
  background: var(--s2);
  color: var(--text);
}
.ds-nv {font-family:var(--font-geist-sans, Geist),sans-serif;font-size:14px;line-height:1.5;}
.ds-nv:focus-visible {outline:2px solid var(--blue);outline-offset:3px;}
.ds-nv {text-decoration:none;}

.ds-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 22px;
  padding: 0 8px;
  border-radius: 999px;
  border: 1px solid var(--line2);
  font-size: 12px;
  color: var(--muted);
  white-space: nowrap;
  flex-shrink: 0;
}
.ds-badge.ds-green {
  color: var(--green);
  border-color: rgba(74, 222, 128, 0.3);
  background: rgba(74, 222, 128, 0.08);
}
.ds-pdot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
  flex: none;
}
.ds-badge {font-family:var(--font-geist-sans, Geist),sans-serif;font-size:14px;line-height:1.5;}
.ds-badge:focus-visible {outline:2px solid var(--blue);outline-offset:3px;}
.ds-badge {font-size:12px;}

.ds-card {
  background: var(--s1);
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
}
.ds-card-h {
  padding: 24px 28px 0;
}
.ds-card-h h1 {
  font-size: 20px;
  font-weight: 600;
  letter-spacing: -0.015em;
}
.ds-card-h p {
  color: var(--muted);
  margin-top: 4px;
  max-width: 600px;
}
.ds-card-b {
  padding: 20px 28px 24px;
}
.ds-card {font-family:var(--font-geist-sans, Geist),sans-serif;font-size:14px;line-height:1.5;}
.ds-card:focus-visible {outline:2px solid var(--blue);outline-offset:3px;}
.ds-card h1,.ds-card p {margin:0;} .ds-card {color:var(--text);}

.ds-citation {
  display: inline-grid;
  place-items: center;
  min-width: 18px;
  height: 18px;
  padding: 0 4px;
  border-radius: 4px;
  background: var(--s2);
  border: 1px solid var(--line2);
  font:
    500 11px var(--font-geist-mono),
    monospace;
  color: var(--muted);
  vertical-align: 1px;
  margin: 0 1px;
  cursor: pointer;
}
.ds-citation.ds-on,
.ds-etabs .ds-on {
  background: #2563eb;
  border-color: #2563eb;
  color: white;
}
.ds-citation:hover {
  border-color: var(--blue);
  color: var(--text);
}
.ds-citation {font-family:var(--font-geist-sans, Geist),sans-serif;font-size:14px;line-height:1.5;}
.ds-citation:focus-visible {outline:2px solid var(--blue);outline-offset:3px;}
.ds-citation {font:500 11px var(--font-geist-mono, Geist Mono),monospace;}
